function toMs(t) {
    if (!t) return Date.now();

    const s = String(t);

    if (/^\d+$/.test(s)) {
        if (s.length >= 18) return Math.floor(Number(s) / 1e6);
        if (s.length === 13) return Number(s);
        if (s.length === 10) return Number(s) * 1000;
    }

    return new Date(t).getTime();
}

function timeTH(ms) {
    const d = new Date(ms);
    const p = n => String(n).padStart(2, "0");

    const y = d.getFullYear();
    const m = p(d.getMonth() + 1);
    const da = p(d.getDate());
    const h = p(d.getHours());
    const mi = p(d.getMinutes());
    const se = p(d.getSeconds());

    return {
        timestamp_th: `${y}-${m}-${da} ${h}:${mi}:${se}`,
        date_th: `${y}-${m}-${da}`,
        time_th: `${h}:${mi}:${se}`
    };
}

function machine(sensorId) {
    const s = String(sensorId);

    if (s.startsWith("300")) return ["weathersensor", "model_weather_300"];
    if (s.startsWith("400")) return ["weathersensor", "model_weather_400"];
    if (s.startsWith("500")) return ["power_environment_sensor", "model_power_env_500"];
    if (s.startsWith("200")) return ["soilsensor", "model_soil"];

    return ["unknown", "unknown_model"];
}

function normalize(raw) {
    if (raw && typeof raw === "object" && !Object.keys(raw).some(k => /^SS\d+/.test(k))) {
        const mapped = {};

        for (const [src, key] of Object.entries(NODE02_MAP)) {
            if (raw[src] !== undefined) {
                mapped[key] = raw[src];
            }
        }

        if (Object.keys(mapped).length) return mapped;
    }

    if (raw && typeof raw === "object") return raw;

    if (typeof raw === "string") {
        const m = raw.match(/^([^:]+?)\s*:\s*(.+)$/);
        if (!m) return {};

        return {
            [m[1].trim()]: m[2].trim()
        };
    }

    if (msg.topic && /^SS\d+/.test(msg.topic)) {
        return {
            [msg.topic]: raw
        };
    }

    return {};
}

