function mapSeries(rows) {
  return (rows || [])
    .filter(r => r.value !== null && r.value !== undefined)
    .map(r => ({ time: r.time, value: Number(r.value) }));
}

function statRow(rows) {
  let r = rows?.[0] || {};
  return {
    min: r.min !== undefined && r.min !== null ? Number(r.min) : null,
    max: r.max !== undefined && r.max !== null ? Number(r.max) : null,
    mean: r.mean !== undefined && r.mean !== null ? Number(r.mean) : null
  };
}

function regressionRow(rows) {
  let r = null;
  if (Array.isArray(rows) && rows.length > 0) {
    r = Array.isArray(rows[0]) ? rows[0][0] : rows[0];
  }
  r = r || {};
  return {
    m: r.m !== undefined && r.m !== null ? Number(r.m) : null,
    b: r.b !== undefined && r.b !== null ? Number(r.b) : null,
    predict_next: r.predict_next !== undefined && r.predict_next !== null ? Number(r.predict_next) : null,
    next_1d: null,
    next_1w: null
  };
}

