    min: r.min !== undefined && r.min !== null ? Number(r.min) : null,
    max: r.max !== undefined && r.max !== null ? Number(r.max) : null,
    mean: r.mean !== undefined && r.mean !== null ? Number(r.mean) : null
  };
}

function regressionRow(rows) {
